CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE INDEX CONCURRENTLY IF NOT EXISTS street_locality_street_name_trgm_idx
ON gnaf.street_locality USING GIN (street_name gin_trgm_ops);

CREATE INDEX CONCURRENTLY IF NOT EXISTS address_detail_street_locality_idx
ON gnaf.address_detail (street_locality_pid) WHERE confidence > -1;

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_adg_address_coordinates
ON gnaf.address_default_geocode (address_detail_pid) INCLUDE (latitude, longitude)
WHERE latitude IS NOT NULL
AND longitude IS NOT NULL;

CREATE INDEX CONCURRENTLY idx_street_locality_name_trgm
ON gnaf.street_locality
USING GIN (street_name gin_trgm_ops);

ANALYZE gnaf.street_locality;
ANALYZE gnaf.address_detail;
ANALYZE gnaf.address_default_geocode;


CREATE OR REPLACE VIEW gnaf.address_view AS

SELECT
    AD.ADDRESS_DETAIL_PID,
    AD.STREET_LOCALITY_PID,
    AD.LOCALITY_PID,
    AD.BUILDING_NAME,

    AD.LOT_NUMBER_PREFIX,
    AD.LOT_NUMBER,
    AD.LOT_NUMBER_SUFFIX,

    FTA.NAME AS FLAT_TYPE,
    AD.FLAT_NUMBER_PREFIX,
    AD.FLAT_NUMBER,
    AD.FLAT_NUMBER_SUFFIX,

    LTA.NAME AS LEVEL_TYPE,
    AD.LEVEL_NUMBER_PREFIX,
    AD.LEVEL_NUMBER,
    AD.LEVEL_NUMBER_SUFFIX,

    AD.NUMBER_FIRST_PREFIX,
    AD.NUMBER_FIRST,
    AD.NUMBER_FIRST_SUFFIX,
    AD.NUMBER_LAST_PREFIX,
    AD.NUMBER_LAST,
    AD.NUMBER_LAST_SUFFIX,

    SL.STREET_NAME,
    SL.STREET_CLASS_CODE,
    SCA.NAME AS STREET_CLASS_TYPE,
    SL.STREET_TYPE_CODE,
    SL.STREET_SUFFIX_CODE,
    SSA.NAME AS STREET_SUFFIX_TYPE,

    L.LOCALITY_NAME,
    ST.STATE_ABBREVIATION,

    AD.POSTCODE,

    ADG.LATITUDE,
    ADG.LONGITUDE,
    GTA.NAME AS GEOCODE_TYPE,

    AD.CONFIDENCE,

    AD.ALIAS_PRINCIPAL,
    AD.PRIMARY_SECONDARY,

    AD.LEGAL_PARCEL_ID,
    AD.DATE_CREATED

FROM gnaf.ADDRESS_DETAIL AD

         LEFT JOIN gnaf.FLAT_TYPE_AUT FTA ON AD.FLAT_TYPE_CODE = FTA.CODE
         LEFT JOIN gnaf.LEVEL_TYPE_AUT LTA ON AD.LEVEL_TYPE_CODE = LTA.CODE
         JOIN gnaf.STREET_LOCALITY SL ON AD.STREET_LOCALITY_PID = SL.STREET_LOCALITY_PID
         LEFT JOIN gnaf.STREET_SUFFIX_AUT SSA ON SL.STREET_SUFFIX_CODE = SSA.CODE
         LEFT JOIN gnaf.STREET_CLASS_AUT SCA ON SL.STREET_CLASS_CODE = SCA.CODE
         JOIN gnaf.LOCALITY L ON AD.LOCALITY_PID = L.LOCALITY_PID
         JOIN gnaf.ADDRESS_DEFAULT_GEOCODE ADG ON AD.ADDRESS_DETAIL_PID = ADG.ADDRESS_DETAIL_PID
         LEFT JOIN gnaf.GEOCODE_TYPE_AUT GTA ON ADG.GEOCODE_TYPE_CODE = GTA.CODE
         JOIN gnaf.STATE ST ON L.STATE_PID = ST.STATE_PID

WHERE AD.CONFIDENCE > -1;
